import sys

def solve():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        parts = list(map(int, line.split()))
        if len(parts) != 3:
            return
        n, d, l = parts
    except ValueError:
        return

    if n == 2:
        if abs(d) > l - 1:
            print("-1")
            return
        if d >= 0:
            a1 = d + 1
            a2 = 1
        else:
            a1 = 1
            a2 = 1 - d
        if 1 <= a1 <= l and 1 <= a2 <= l:
            print(f"{a1} {a2}")
        else:
            print("-1")
        return

    coeff = [1] * n
    for _ in range(n - 1):
        coeff[-2] -= coeff[-1]
        coeff.pop()

    target = d
    current_sum = sum(coeff[i] for i in range(n))

    if current_sum == 0:
        if target == 0:
            print(" ".join(["1"] * n))
            return
        else:
            print("-1")
            return

    base = 1
    values = [base] * n
    current_val = sum(values[i] * coeff[i] for i in range(n))

    needed = target - current_val

    if needed == 0:
        print(" ".join(map(str, values)))
        return

    pos_indices = [i for i in range(n) if coeff[i] > 0]
    neg_indices = [i for i in range(n) if coeff[i] < 0]

    if needed > 0:
        indices = pos_indices
    else:
        indices = neg_indices
        needed = -needed

    if not indices:
        print("-1")
        return

    remaining = needed
    for i in indices:
        c = abs(coeff[i])
        max_add = l - values[i]
        add = min(max_add, remaining // c)
        if add > 0:
            values[i] += add
            remaining -= add * c

    if remaining > 0:
        print("-1")
        return

    if needed < 0:
        for i in indices:
            c = abs(coeff[i])
            max_sub = values[i] - 1
            sub = min(max_sub, remaining // c)
            if sub > 0:
                values[i] -= sub
                remaining -= sub * c

        if remaining > 0:
            print("-1")
            return

    final_check = sum(values[i] * coeff[i] for i in range(n)) != target
    if final_check:
        print("-1")
        return

    if not all(1 <= x <= l for x in values):
        print("-1")
        return

    print(" ".join(map(str, values)))

if __name__ == "__main__":
    solve()
